    // dp[i] = max profit using i grams of dough
    val dp = IntArray(n + 1) { 0 }

    // Process plain buns (unbounded knapsack)
    for (i in c0..n) {
        dp[i] = maxOf(dp[i], dp[i - c0] + d0)
    }

    // Process each stuffing type (bounded knapsack)
    for ((c, d, maxCount) in stuffings) {
        // Binary optimization for bounded knapsack
        var k = 1
        var remaining = maxCount
        while (remaining > 0) {
            val take = minOf(k, remaining)
            val cost = c * take
            val value = d * take
            for (i in n downTo cost) {
                dp[i] = maxOf(dp[i], dp[i - cost] + value)
            }
            remaining -= take
            k *= 2
        }
    }

    println(dp[n])
